CREATE TABLE IF NOT EXISTS booking_rules ( id TEXT PRIMARY KEY, tenant_id TEXT REFERENCES tenants(id) ON DELETE CASCADE, rule_type TEXT NOT NULL, start_time TEXT, end_time TEXT, timezone TEXT, is_available BOOLEAN DEFAULT true, created_at TIMESTAMPTZ DEFAULT NOW(), updated_at TIMESTAMPTZ DEFAULT NOW(), UNIQUE(tenant_id, rule_type) ); ALTER TABLE booking_rules ENABLE ROW LEVEL SECURITY; CREATE POLICY tenant_isolation_booking_rules ON booking_rules USING (tenant_id::text = current_setting('app.current_tenant', true)) WITH CHECK (tenant_id::text = current_setting('app.current_tenant', true));
